-- =====================================================================
-- PetMatch: parceiros reais, loja e anúncios de demonstração
-- Rode DEPOIS de supabase-add-plans-roles-features.sql. Pode rodar mais de uma vez.
-- Remove os exemplos antigos (nomes com "(exemplo)") e recria tudo.
-- =====================================================================

delete from public.products where name like '%(exemplo)%' or (owner_id is null and image_url like 'images/%');
delete from public.ads      where advertiser like '%(exemplo)%' or title like '%(exemplo)%' or (owner_id is null and advertiser in ('Prefeitura', 'Loja PetMatch'));
delete from public.partners where name like '%(exemplo)%' or (owner_id is null and website = 'https://www.petz.com.br');

-- ---------- ESTABELECIMENTOS REAIS (uma loja da rede Petz em cada capital) ----------
